command:
const sand = await Dialog.confirm({
    title: "Dowsing Rod",
    content: "Is this area a sandy or rocky area (beach, desert, cave, mountain, etc.)?",
    yes: () => 1,
    no: () => 0
});
const book = await Dialog.confirm({
    title: "Dowsing Rod",
    content: "Are you currently benefitting from \"Dowsing for Dummies\"?",
    yes: () => 1,
    no: () => 0
});
const stunt = +canvas.tokens.controlled[0].actor._itemTypes.edge.some(e => e.name.includes("Dowsing")); //searches for an edge with Dowsing in it - meant for the skill stunt
const resonance = 3 * +canvas.tokens.controlled[0].actor._itemTypes.feat.some(e => e.name.includes("Crystal Resonance"));

let roll = await new Roll(`${actor.system.skills.occultEd.value.total+sand+stunt+resonance+book}d6x=6cs>=4`).roll({async: true});
await roll.toMessage();

let table = game.tables.getName("Shards");

    await table.drawMany(roll.total,{displayChat:true});
